    "body": "<!doctype html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\" />\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n  <meta name=\"description\" content=\"Kinetik helps ambitious teams build momentum.\" />\n  <title>Kinetik — Move work forward</title>\n  <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\" />\n  <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin />\n  <link href=\"https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=DM+Sans:opsz,wght@9..40,400;9..40,500;9..40,600;9..40,700&family=Playfair+Display:ital,wght@600;700&display=swap\" rel=\"stylesheet\" />\n  <link rel=\"stylesheet\" href=\"styles.css\" />\n</head>\n<body>\n  <div class=\"noise\" aria-hidden=\"true\"></div>\n  <header class=\"nav container\">\n    <a class=\"brand\" href=\"#top\" aria-label=\"Kinetik home\"><span class=\"brand-mark\">K</span> kinetik.</a>\n    <nav class=\"nav-links\" aria-label=\"Main navigation\">\n      <a href=\"#approach\">Approach</a><a href=\"#work\">Our work</a><a href=\"#notes\">Notes</a>\n    </nav>\n    <a class=\"nav-cta\" href=\"#contact\">Start a project <span>↗</span></a>\n    <button class=\"menu\" aria-label=\"Open navigation\" aria-expanded=\"false\"><i></i><i></i></button>\n  </header>\n\n  <main id=\"top\">\n    <section class=\"hero container\">\n      <div class=\"eyebrow reveal\">Independent creative studio <span></span> Est. 2017</div>\n      <h1 class=\"reveal\">Ideas that<br><em>move people.</em></h1>\n      <div class=\"hero-bottom reveal\">\n        <p>We partner with forward-thinking teams to turn clarity into culture, and momentum into meaningful change.</p>\n        <a class=\"round-link\" href=\"#approach\" aria-label=\"Explore our approach\"><span>↓</span></a>\n      </div>\n      <div class=\"orb orb-one\"></div><div class=\"orb orb-two\"></div>\n    </section>\n\n    <section class=\"marquee\" aria-label=\"Our capabilities\"><div class=\"marquee-track\"><span>Brand strategy</span><b>✦</b><span>Digital experiences</span><b>✦</b><span>Campaigns with gravity</span><b>✦</b><span>Brand strategy</span><b>✦</b><span>Digital experiences</span><b>✦</b><span>Campaigns with gravity</span><b>✦</b></div></section>\n\n    <section class=\"intro container\" id=\"approach\">\n      <div class=\"section-label reveal\">01 / What we believe</div>\n      <div class=\"intro-copy reveal\"><p class=\"display-copy\">The best work doesn't just look <em>different.</em> It makes a difference.</p><p>We bring an uncommon mix of strategic rigor and creative instinct to the questions that matter most. Then, we make the answer impossible to ignore.</p><a class=\"text-link\" href=\"#contact\">How we work <span>→</span></a></div>\n    </section>\n\n    <section class=\"selected\" id=\"work\">\n      <div class=\"container selected-head\"><div class=\"section-label reveal\">02 / Selected momentum</div><a class=\"text-link reveal\" href=\"#contact\">See all projects <span>→</span></a></div>\n      <div class=\"project-grid container\">\n        <article class=\"project large reveal\"><a href=\"#contact\"><div class=\"project-image image-sun\"><div class=\"sun\"></div><span class=\"image-word\">SOL</span></div><div class=\"project-meta\"><div><h2>Solace</h2><p>Identity, digital, launch</p></div><span>2024 ↗</span></div></a></article>\n        <article class=\"project reveal\"><a href=\"#contact\"><div class=\"project-image image-tide\"><div class=\"tide-lines\"></div><span>01:49</span></div><div class=\"project-meta\"><div><h2>Tide</h2><p>Strategy, campaign</p></div><span>2024 ↗</span></div></a></article>\n        <article class=\"project reveal\"><a href=\"#contact\"><div class=\"project-image image-green\"><div class=\"green-shape\"></div><strong>We<br>grow<br>good.</strong></div><div class=\"project-meta\"><div><h2>Verdant</h2><p>Brand world, packaging</p></div><span>2023 ↗</span></div></a></article>\n      </div>\n    </section>\n\n    <section class=\"statement container\" id=\"notes\"><div class=\"section-label reveal\">03 / A note from us</div><blockquote class=\"reveal\">Stay curious.<br>Be <em>useful.</em><br>Make it count.</blockquote><p class=\"reveal\">Good energy is contagious. So is good work.</p></section>\n\n    <section class=\"contact\" id=\"contact\"><div class=\"container contact-inner\"><div class=\"section-label\">04 / Make a move</div><div><p>Have a challenge worth caring about?</p><a class=\"contact-link\" href=\"mailto:hello@kinetik.studio\">Let's talk <span>↗</span></a></div></div></section>\n  </main>\n  <footer class=\"footer container\"><a class=\"brand\" href=\"#top\"><span class=\"brand-mark\">K</span> kinetik.</a><p>© 2025 Kinetik Studio</p><div><a href=\"#\">Instagram</a><a href=\"#\">LinkedIn</a></div></footer>\n  <script src=\"script.js\"></script>\n</body>\n</html>",
